<div class="grid gap-5 lg:grid-cols-2"><section class="card p-6"><h2 class="text-sm font-semibold">Colores personalizados</h2><p class="mb-5 mt-1 text-xs text-slate-500">Cada color se conserva hasta que vuelvas a modificarlo.</p><div class="grid gap-5 sm:grid-cols-2">@foreach(['primary_color'=>['Color principal','#6366f1'],'sidebar_color'=>['Menú lateral','#10172a'],'accent_color'=>['Color de acento','#22d3ee'],'background_color'=>['Fondo general','#f5f7fb']] as $key=>[$label,$fallback])<label class="text-xs font-medium text-slate-600">{{$label}}<div class="mt-2 flex gap-2"><input id="{{$key}}" type="color" name="{{$key}}" value="{{old($key,$settings[$key]??$fallback)}}" class="h-11 w-14 rounded border"><output data-for="{{$key}}" class="grid flex-1 place-items-center rounded-xl border border-slate-200 font-mono text-xs"></output></div></label>@endforeach</div></section>
