<script>const fonts={instrument:'Instrument Sans,system-ui,sans-serif',inter:'Inter,Arial,sans-serif',system:'system-ui,sans-serif',humanist:'Segoe UI,Trebuchet MS,sans-serif',nunito:'Nunito,Trebuchet MS,sans-serif',poppins:'Poppins,Century Gothic,sans-serif',roboto:'Roboto,Arial,sans-serif',lato:'Lato,Arial,sans-serif',serif:'Georgia,Cambria,serif',merriweather:'Merriweather,Georgia,serif',georgia:'Georgia,serif',mono:'Cascadia Code,Consolas,monospace'},keys=['primary_color','sidebar_color','accent_color','background_color'],byId=id=>document.getElementById(id);function preview(){keys.forEach(k=>document.querySelector(`[data-for="${k}"]`).textContent=byId(k).value);byId('preview-sidebar').style.background=byId('sidebar_color').value;byId('preview-logo').style.background=`linear-gradient(135deg,${byId('primary_color').value},${byId('accent_color').value})`;byId('preview-button').style.background=byId('primary_color').value;byId('identity-preview').style.background=byId('background_color').value;byId('font-preview').style.fontFamily=fonts[byId('font_family').value]}document.querySelectorAll('input[type=color]').forEach(input=>input.addEventListener('input',preview));byId('font_family').addEventListener('change',preview);preview();</script>
